package com.hms.appointments;
import com.hms.tenancy.*; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/patients/{patientId}/privacy") public class PatientPrivacyController {private final TenantRepository tenants;private final PatientRepository patients;public PatientPrivacyController(TenantRepository t,PatientRepository p){tenants=t;patients=p;} @GetMapping public Map<String,Object> status(@PathVariable String tenantSlug,@PathVariable UUID patientId){Patient p=patient(tenantSlug,patientId);return Map.of("patientId",p.getId(),"anonymized",p.isAnonymized());} @DeleteMapping @ResponseStatus(org.springframework.http.HttpStatus.NO_CONTENT) public void anonymize(@PathVariable String tenantSlug,@PathVariable UUID patientId){Patient p=patient(tenantSlug,patientId);p.anonymize();patients.save(p);} private Patient patient(String slug,UUID id){UUID t=tenants.findBySlug(slug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(slug));return patients.findById(id).filter(p->p.getTenantId().equals(t)).orElseThrow(()->new IllegalArgumentException("Patient not found"));}}
